-- 223: a relocated ride's track is the same ride wherever it stood (Carter,
-- 2026-11-24: "for stuff like dominator geauga lake make sure you're checking
-- relocations too because i'm sure dominator kings dominion has stats").
-- Blank height, speed, length, inversions, duration, maker and model on a
-- same_ride row are filled from its home row first, then from any other row
-- of the ride. Never overwrites a value. Opening/closing dates are per
-- location and are not copied. Provenance: coaster_sources 'manual' with ref
-- 'relocation (223)'. Re-run after linking relocations; a second run is a
-- no-op. No activity rows (filling stats gets none, 2026-11-05).
INSERT OR REPLACE INTO coaster_sources (coaster_id, field, source, ref) SELECT c.id, 'h', 'manual', 'relocation (223)' FROM coasters c JOIN same_ride sr ON sr.coaster = c.id WHERE c.h IS NULL AND EXISTS (SELECT 1 FROM same_ride b JOIN coasters o ON o.id = b.coaster WHERE b.ride = sr.ride AND b.coaster <> c.id AND o.h IS NOT NULL);
UPDATE coasters SET h = COALESCE((SELECT o.h FROM same_ride sr JOIN coasters o ON o.id = sr.ride WHERE sr.coaster = coasters.id AND o.id <> coasters.id), (SELECT o.h FROM same_ride sr JOIN same_ride b ON b.ride = sr.ride JOIN coasters o ON o.id = b.coaster WHERE sr.coaster = coasters.id AND b.coaster <> coasters.id AND o.h IS NOT NULL ORDER BY o.id DESC LIMIT 1)) WHERE h IS NULL AND id IN (SELECT coaster FROM same_ride);
INSERT OR REPLACE INTO coaster_sources (coaster_id, field, source, ref) SELECT c.id, 's', 'manual', 'relocation (223)' FROM coasters c JOIN same_ride sr ON sr.coaster = c.id WHERE c.s IS NULL AND EXISTS (SELECT 1 FROM same_ride b JOIN coasters o ON o.id = b.coaster WHERE b.ride = sr.ride AND b.coaster <> c.id AND o.s IS NOT NULL);
UPDATE coasters SET s = COALESCE((SELECT o.s FROM same_ride sr JOIN coasters o ON o.id = sr.ride WHERE sr.coaster = coasters.id AND o.id <> coasters.id), (SELECT o.s FROM same_ride sr JOIN same_ride b ON b.ride = sr.ride JOIN coasters o ON o.id = b.coaster WHERE sr.coaster = coasters.id AND b.coaster <> coasters.id AND o.s IS NOT NULL ORDER BY o.id DESC LIMIT 1)) WHERE s IS NULL AND id IN (SELECT coaster FROM same_ride);
